//go:build ignore

package main

import "os"

// gen_stubs.go writes temporary bootstrap stubs that allow pkg/streamplace to
// compile before cbor_gen.go exists. These are needed because lexgen generates
// union marshal code (e.g. Livestream_Activity.MarshalCBOR) that calls CBOR
